22	
23	    /** A pragmatic syntactic email check: a local part, an '@', and a dotted domain,
24	     *  none containing whitespace or a second '@'. */
25	    private static final Pattern EMAIL_PATTERN =
26	            Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
27	
28	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
29	            throws RequiredFieldsException {
30	        List<String> errors = new ArrayList<>();
31	        checkField("firstName", request.getFirstName(), errors);
32	        checkField("lastName", request.getLastName(), errors);
33	        checkField("address", request.getAddress(), errors);
34	        checkField("city", request.getCity(), errors);
35	        checkField("telephone", request.getTelephone(), errors);
36	        if (!errors.isEmpty()) {
37	            throw new RequiredFieldsException(errors);
38	        }
39	        // Normalize the telephone: strip every non-digit, then require exactly 10 digits.
40	        String telephone = request.getTelephone().replaceAll("\\D", "");
41	        if (telephone.length() != 10) {
42	            throw new RequiredFieldsException(List.of("telephone"));
43	        }
44	        request.setTelephone(telephone);
45	        // Email is optional; when present it must be syntactically valid and is
46	        // stored and returned lower-cased.
47	        String email = request.getEmail();
48	        if (email != null && !email.isBlank()) {
49	            if (!EMAIL_PATTERN.matcher(email).matches()) {
50	                throw new RequiredFieldsException(List.of("email"));
51	            }
52	            request.setEmail(email.toLowerCase());
53	        }
54	        validated.set(request);
55	    }
56	
57	    private static void checkField(String name, String value, List<String> errors) {
58	        if (value == null || value.isBlank()) {
59	            errors.add(name);
60	        }
61	    }
